static void require(bool ok,const char *message){if(!ok)throw std::runtime_error(message);}
static void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);}
static QByteArray read(const QString &path){QFile f(path);require(f.open(QIODevice::ReadOnly),"Preview artifact unavailable");return f.readAll();}
static void write(const QString &path,const QByteArray &data){QFile f(path);require(f.open(QIODevice::WriteOnly)&&f.write(data)==data.size(),"Preview artifact write failed");}
int main(int argc,char **argv){QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);QApplication app(argc,argv);app.setOrganizationName("GMATTests");app.setApplicationName("NasaScriptPreview");try{
 require(argc==2&&acceptanceWidgetPlatform()&&QApplication::platformName()!="offscreen","Native script preview startup required");TestSettings settings;QTemporaryDir files;require(files.isValid(),"Preview fixtures unavailable");const auto startup=QFileInfo(argv[1]).absoluteFilePath();QDir::setCurrent(QFileInfo(startup).absolutePath());const auto artifact=qEnvironmentVariable("GMAT_QT_ACCEPTANCE_DIR");auto save=[&](const QString &name,const QByteArray &data){if(!artifact.isEmpty())write(artifact+"/"+name,data);};const auto report=files.filePath("preview values Ω.csv"),saved=files.filePath("preview Ω.script");MainWindow window;window.resize(1150,850);window.show();require(window.initialize(startup),"Preview runtime unavailable");acceptanceView(window);auto *source=window.findChild<QPlainTextEdit *>("scriptEditor");auto *area=window.findChild<QMdiArea *>("workspace");auto *resources=window.findChild<QTreeWidget *>("Resources");const QString script="% keep preview source Ω\nEarth.Mu = 400000;\nCreate Spacecraft Sat;\nSat.DateFormat = A1ModJulian;\nSat.Epoch = '21545';\nCreate ForceModel FM;\nFM.PrimaryBodies = {};\nFM.PointMasses = {Earth};\nCreate Propagator Prop;\nProp.FM = FM;\nCreate Variable Keep;\nKeep = 41;\nCreate ReportFile Values;\nValues.Filename = '"+report+"';\nValues.WriteHeaders = false;\nValues.FixedWidth = false;\nValues.Delimiter = ',';\nValues.Precision = 25;\nBeginMissionSequence;\nPropagate 'Preview coast' Prop(Sat) {Sat.ElapsedSecs = 60};\nReport Values Sat.A1ModJulian Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Keep;\n";source->setPlainText(script);QJsonArray results,inspectors;
 auto run=[&](const QString &phase){require(window.runMission()==MainWindow::RunResult::Completed,"Preview mission failed");const auto raw=read(report);const auto fields=QString::fromUtf8(raw).trimmed().split(',');require(fields.size()==5,"Preview report cardinality differs");QJsonArray row;for(const auto &f:fields){bool ok=false;const double x=f.toDouble(&ok);require(ok&&std::isfinite(x),"Preview report nonfinite");row.append(x);}require(row.last().toDouble()==41&&std::abs((row.first().toDouble()-21545)*86400-60)<1e-5,"Preview sentinel/epoch differs");results.append(QJsonObject{{"phase",phase},{"values",row}});save(phase+".csv",raw);save("reports.json",QJsonDocument(results).toJson());return raw;};const auto baseline=run("baseline");const auto original=source->toPlainText();const int undo=source->document()->availableUndoSteps();
 auto inspect=[&](QWidget &owner,QPushButton *button,const QString &kind){require(button&&button->isVisible()&&button->isEnabled(),"Preview Show script button hidden/disabled");bool seen=false;std::exception_ptr error;QTimer timer;timer.setInterval(20);QObject::connect(&timer,&QTimer::timeout,&owner,[&]{auto *dialog=qobject_cast<QDialog *>(QApplication::activeModalWidget());if(!dialog||dialog->objectName()!="inspectionDialog")return;timer.stop();seen=true;try{require(QTest::qWaitForWindowExposed(dialog->windowHandle()),"Script inspector native surface not exposed");acceptanceView(*dialog);auto *text=dialog->findChild<QPlainTextEdit *>("inspectionText");require(text&&text->isVisible()&&text->isReadOnly(),"Script inspector text hidden or editable");const auto value=text->toPlainText();if(kind=="resource")require(QRegularExpression("Earth\\.Mu\\s*=\\s*400000(?:\\.0*)?\\s*;").match(value).hasMatch()&&!value.contains("400001"),"Body preview does not show applied Mu without pending draft");else require(value.contains("Propagate")&&value.contains("Preview coast")&&QRegularExpression("ElapsedSecs\\s*=\\s*60(?:\\.0*)?").match(value).hasMatch(),"Command preview does not show applied coast/stop");text->setFocus();QTest::keyClicks(text,"SHOULD_NOT_EDIT");require(text->toPlainText()==value&&source->toPlainText()==original&&source->document()->availableUndoSteps()==undo,"Read-only inspector changed text/source/history");inspectors.append(QJsonObject{{"kind",kind},{"text",value},{"read_only",true},{"visible",true},{"native_exposed",dialog->windowHandle()->isExposed()},{"platform",QApplication::platformName()}});save("inspectors.json",QJsonDocument(inspectors).toJson());auto *close=dialog->findChild<QDialogButtonBox *>()->button(QDialogButtonBox::Close);require(close&&close->isEnabled(),"Inspector Close unavailable");QTest::mouseClick(close,Qt::LeftButton);require(!dialog->isVisible(),"Inspector Close did not close");}catch(...){error=std::current_exception();dialog->reject();}});timer.start();QTest::mouseClick(button,Qt::LeftButton);timer.stop();if(error)std::rethrow_exception(error);require(seen,"Native script inspector did not open");};
 auto items=resources->findItems("Earth",Qt::MatchExactly|Qt::MatchRecursive);require(items.size()==1,"Earth resource tree item missing");resources->itemDoubleClicked(items.first(),0);events();auto *child=area->activeSubWindow();auto *panel=child ? dynamic_cast<CelestialBodyPanel *>(child->widget()) : nullptr;require(panel,"Actual body preview MDI panel missing");child->showNormal();panel->findChild<QTabWidget *>("bodyPages")->setCurrentIndex(0);auto *mu=panel->findChild<QLineEdit *>("body_Mu");require(mu&&mu->isVisible()&&!mu->isReadOnly(),"Pending Mu control not visible/editable");mu->selectAll();QTest::keyClicks(mu,"400001");require(mu->text()=="400001"&&panel->hasChanges()&&source->toPlainText()==original,"Visible pending Mu did not remain isolated");acceptanceView(*child);inspect(*panel,panel->findChild<QPushButton *>("showScript"),"resource");auto *earth=dynamic_cast<CelestialBody *>(Moderator::Instance()->GetConfiguredObject("Earth"));require(earth&&earth->GetRealParameter(earth->GetParameterID("Mu"))==400000&&mu->text()=="400001"&&panel->hasChanges(),"Body inspector changed native applied or pending value");panel->discardChanges();child->close();events();
 const auto snapshot=window.missionSnapshot();int command=-1;for(int i=0;i<snapshot.nodes.size();++i)if(snapshot.nodes[i].type=="Propagate")command=i;require(command>=0,"Preview coast mission node missing");auto *mission=window.findChild<QTreeWidget *>("Mission");QTreeWidgetItem *entry=nullptr;QTreeWidgetItemIterator it(mission);while(*it){if((*it)->data(0,Qt::UserRole).isValid()&&(*it)->data(0,Qt::UserRole).toInt()==command){entry=*it;break;}++it;}require(entry,"Preview command tree item missing");mission->itemDoubleClicked(entry,0);events();child=area->activeSubWindow();auto *commandPanel=child ? dynamic_cast<CommandEditor *>(child->widget()) : nullptr;require(commandPanel,"Actual command preview MDI panel missing");child->showNormal();acceptanceView(*child);inspect(*commandPanel,commandPanel->findChild<QPushButton *>("showScript"),"command");require(!commandPanel->hasChanges()&&source->toPlainText()==original,"Command inspector modified applied command/source");commandPanel->discardChanges();child->close();events();require(run("after-inspectors")==baseline,"Script inspection altered native calculations");require(window.saveScriptTo(saved)&&window.loadScript(saved)&&source->toPlainText()==original,"Preview Unicode save/reopen changed source");require(run("reopened")==baseline,"Reopened inspected mission changed calculations");save("mission.script",original.toUtf8());const QJsonObject proof{{"checkpoint","native-script-previews"},{"outcome","passed"},{"family","script-preview"},{"native_inspectors",inspectors.size()},{"raw_report_values",15},{"facets",QJsonArray{"actual-body-and-command-mdi-show-script","native-exposed-read-only-inspector-text","applied-body-mu-excludes-visible-pending-draft","source-history-report-and-unicode-reopen-invariance"}},{"scope","Two actual paced native script inspectors, typed visible pending body Mu and applied command coast text. Preserved legacy companion covers generic resource/command draft isolation. Selected types/text/keyboard probe only, not all resources/commands/fonts/OS-input/platform/stress/scientific accuracy."}};save("proof.json",QJsonDocument(proof).toJson());std::cout<<"NASA_CHECK "<<QJsonDocument(proof).toJson(QJsonDocument::Compact).constData()<<std::endl;return 0;
 }catch(BaseException &e){std::cerr<<"FAIL "<<e.GetFullMessage()<<std::endl;}catch(std::exception &e){std::cerr<<"FAIL "<<e.what()<<std::endl;}return 1;}
